-- =====================================================================
-- Дополнительные данные «Флористического центра» (выполняется после
-- тестовые_данные.sql): около сотни записей в основных таблицах.
--
-- * Сеть салонов в Москве: ~100 сотрудников, ~130 клиентов, ~130 растений
--   с реальными сортами и закупочными ценами, ~100 шаблонов книги рецептов.
-- * Заказы за прошлый и текущий год с сезонностью: пики к 14 февраля,
--   8 марта, 1 сентября, Дню матери и Новому году; пионы — только
--   в мае–июле, хвоя — в ноябре–январе, тюльпаны — в основном весной.
-- * Даты считаются от текущего года (функция pg_temp.д), заказы «из
--   будущего» отбрасываются — скрипт можно запускать в любой момент.
-- * Склад ведут триггеры: сначала поставки (заявки, переведённые в
--   «выполнена», пополняют остаток через тр_поставка), затем продажи
--   и списания (тр_склад уменьшает остаток и подставляет цены).
-- * id выдают последовательности; там, где нет естественного ключа
--   (заказы, букеты), id берутся из них заранее во временных таблицах.
-- * Сгенерировано скриптом с фиксированным seed — данные воспроизводимы.
-- =====================================================================

BEGIN;

-- дата: г = 0 — прошлый год, г = 1 — текущий
CREATE FUNCTION pg_temp.д(г INT, м INT, д INT, ч INT, мин INT) RETURNS TIMESTAMP AS $$
    SELECT make_timestamp(extract(year FROM now())::INT - 1 + г, м, д, ч, мин, 0)
$$ LANGUAGE sql STABLE;

