    ('Орхидея ванда', 25, pg_temp.д(1, 10, 18, 15, 27), 'выполнена')
             ) AS в(растение, количество, дата, статус)
        JOIN растения р ON р.название = в.растение
        JOIN поставщики п ON п.id = р.поставщик_id
       ORDER BY в.дата) s;

INSERT INTO заявки_на_закупку (id, растение_id, количество, дата, ожидаемая_дата, статус)
SELECT id, растение_id, количество, дата, (дата + срок_поставки * interval '1 day')::DATE,
       CASE WHEN статус = 'отменена' THEN 'отменена' ELSE 'новая' END
FROM нов_заявки ORDER BY id;

UPDATE заявки_на_закупку SET статус = 'выполнена'
WHERE id IN (SELECT id FROM нов_заявки WHERE статус = 'выполнена');

