      ) AS в(н, дата, клиент, флорист, оплата, курьер, адрес, через_мин, получатель, тел_получателя)
      WHERE в.дата < now()
      ORDER BY в.н) s;

INSERT INTO заказы (id, дата, клиент_id, флорист_id, способ_оплаты, курьер_id,
                    адрес_доставки, время_доставки, получатель, телефон_получателя)
SELECT з.id, з.дата,
       (SELECT id FROM клиенты    WHERE имя = з.клиент),
       (SELECT id FROM сотрудники WHERE фио = з.флорист),
       з.оплата,
       (SELECT id FROM сотрудники WHERE фио = з.курьер),
       з.адрес,
       з.дата + з.через_мин * interval '1 minute',
       з.получатель, з.тел_получателя
FROM нов_заказы з ORDER BY з.id;

-- Букеты: по шаблону флориста заказа (иногда с изменённым составом)
