        JOIN нов_заказы з ON з.н = в.заказ_н
       ORDER BY в.н) s;

INSERT INTO букеты (id, заказ_id, шаблон_id, сложность, время_сборки, цена_продажи)
SELECT б.id, б.заказ_id,
       (SELECT ш.id FROM шаблоны ш JOIN сотрудники с ON с.id = ш.флорист_id
         WHERE с.фио = б.флорист AND ш.название = б.шаблон),
       б.сложность, б.время_сборки, 0
FROM нов_букеты б ORDER BY б.id;

