JOIN растения р ON р.название = в.растение
ORDER BY б.id, р.id;

UPDATE букеты б
   SET цена_продажи = ROUND(рекоменд_цена(б.id) * н.коэф, -1)
  FROM нов_букеты н
 WHERE н.id = б.id;

